#include <bits/stdc++.h>
using namespace std;

const long long mod = 998244353;

long long power(long long x, long long y) {
    long long res = 1;
    x %= mod;
    while (y > 0) {
        if (y & 1) {
            res = (res * x) % mod;
        }
        y >>= 1;
        x = (x * x) % mod;
    }
    return res;
}

long long choose(long long n, long long k) {
    long long num = 1;
    long long denom = 1;
    for (long long i = n - k + 1; i <= n; i++) {
        num = (num * i) % mod;
    }
    for (long long i = 1; i <= k; i++) {
        denom = (denom * i) % mod;
    }
    denom = power(denom, mod - 2);
    return (num * denom) % mod;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long kk;
    cin >> n >> kk;
    if (kk >= n) {
        cout << "0\n";
    } else {
        int k = (int)kk;
        int r = n - k;
        std::vector<long long> rChoose(r + 1);
        rChoose[0] = 1;
        long long numChoose = 1;
        long long denomChoose = 1;
        for (int i = 1; i <= r; i++) {
            numChoose = (numChoose * (r + 1 - i)) % mod;
            denomChoose = (denomChoose * i) % mod;
            rChoose[i] = (numChoose * power(denomChoose, mod - 2)) % mod;
        }
        long long ans = 0;
        long long flipper = 1;
        for (int i = 0; i <= r; i++) {
            long long term = power((long long)(r - i), (long long)n);
            ans += term * flipper * rChoose[i];
            ans %= mod;
            flipper = -flipper;
        }
        ans = (ans * choose(n, k)) % mod;
        if (k > 0) {
            ans = (ans * 2) % mod;
        }
        if (ans < 0) {
            ans += mod;
        }
        cout << ans << "\n";
    }
    return 0;
}
